import Container from 'react-bootstrap/Container';
import Nav from 'react-bootstrap/Nav';
import Navbar from 'react-bootstrap/Navbar';
import { Link } from 'react-router-dom';
import { useFirebase } from '../context/firebase';
const NavBar = () =>{
    const firebase = useFirebase();
    const user = firebase.isLoggedIn;
    return (

            <Navbar bg="dark" data-bs-theme="dark">
        <Container>
            <Navbar.Brand as={Link} to="/">Bookify</Navbar.Brand>
            {user ? (
                <>
                    <Nav className="me-auto">
                        <Nav.Link as={Link} to="/">Home</Nav.Link>
                        <Nav.Link as={Link} to="/addListing">Add Listing</Nav.Link>
                        <Nav.Link as={Link} to="/book/orders">Orders</Nav.Link>
                        <Nav.Link as={Link} to="/user/logOut">Logout</Nav.Link>
                    </Nav>
                </>
            ): (
                <>
                    <Nav className="me-auto">
                        <Nav.Link as={Link} to="/">Home</Nav.Link>
                        <Nav.Link as={Link} to="/addListing">Add Listing</Nav.Link>
                        <Nav.Link as={Link} to="/register">Register</Nav.Link>
                        <Nav.Link as={Link} to="/login">Login</Nav.Link>
                    </Nav>
                </>
            )}
          
        </Container>
      </Navbar>
    )
}

export default NavBar;
