import Button from 'react-bootstrap/Button';
import Form from 'react-bootstrap/Form';
import { useState , useEffect } from 'react';
import { useFirebase } from '../context/firebase';
import {useNavigate} from "react-router-dom";

const LoginPage = () =>{
    const [email , setEmail] = useState("");
    const [password , setPassword] = useState("");
    const [error, setError] = useState(null);
    const firebase = useFirebase();
    const navigate = useNavigate();
    useEffect(()=>{
      if(firebase.isLoggedIn)
      {
        navigate("/");
      }
    },[firebase.isLoggedIn,navigate]);
    const handleLogin = async (e) =>{
      e.preventDefault();
      setError(null);
      try{
        console.log("Signing ....");
        await firebase.LoginUser(email, password);
        console.log("Signed in");
        navigate('/');
      }catch(err){
        console.error(err);
        setError(err.message || err.code || 'Login failed');
      }

    }

    const handleGoogle = async () =>{
      setError(null);
      try{
        await firebase.GoogleLogIn();
        navigate('/');
      }catch(err){
        console.error(err);
        setError(err.message || err.code || 'Google sign-in failed');
      }
    }
    return(
        <div className='container mt-5'>
            <Form onSubmit={handleLogin}>
            {error && <div className="alert alert-danger">{error}</div>}
      <Form.Group className="mb-3" controlId="formBasicEmail">
        <Form.Label>Email address</Form.Label>
        <Form.Control onChange={e=> setEmail(e.target.value)} value={email} type="email" placeholder="Enter email" />
      </Form.Group>

      <Form.Group className="mb-3" controlId="formBasicPassword">
        <Form.Label>Password</Form.Label>
        <Form.Control onChange={e=> setPassword(e.target.value)} value={password} type="password" placeholder="Password" />
      </Form.Group>
      <Button variant="primary" type="submit">
        Log In
      </Button>
    </Form>
    <br />
    <h2>OR</h2>
    <br />
    <Button onClick={handleGoogle}  variant="danger" type="button">
        Google
      </Button>
        </div>
    );
}

export default LoginPage;